_items; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_inquiry_items\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"parent_inquiry_id\\" \\"uuid\\" NOT NULL,\n    \\"inquiry_number\\" \\"text\\" NOT NULL,\n    \\"product_name\\" \\"text\\" NOT NULL,\n    \\"specification\\" \\"text\\",\n    \\"quantity\\" \\"text\\",\n    \\"target_price\\" \\"text\\",\n    \\"status\\" \\"text\\" DEFAULT 'open'::\\"text\\",\n    \\"pipeline_stage\\" \\"text\\" DEFAULT 'new'::\\"text\\",\n    \\"document_sent\\" boolean DEFAULT false,\n    \\"document_sent_at\\" timestamp with time zone,\n    \\"notes\\" \\"text\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"supplier_name\\" \\"text\\",\n    \\"supplier_country\\" \\"text\\",\n    \\"delivery_date\\" \\"date\\",\n    \\"delivery_terms\\" \\"text\\",\n    \\"aceerp_no\\" \\"text\\",\n    \\"purchase_price\\" numeric(15,2),\n    \\"purchase_price_currency\\" \\"text\\" DEFAULT 'USD'::\\"text\\",\n    \\"offered_price\\" numeric(15,2),\n    \\"offered_price_currency\\" \\"text\\" DEFAULT 'USD'::\\"text\\",\n    \\"our_side_status\\" \\"text\\"[] DEFAULT '{}'::\\"text\\"[],\n    \\"price_sent_at\\" timestamp with time zone,\n    \\"coa_sent_at\\" timestamp with time zone,\n    \\"sample_sent_at\\" timestamp with time zone,\n    \\"agency_letter_sent_at\\" timestamp with time zone,\n    \\"remarks\\" \\"text\\",\n    \\"make\\" \\"text\\"\n)","--\n-- Name: crm_inquiry_pricing_options; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_inquiry_pricing_options\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\" NOT NULL,\n    \\"source_type\\" \\"text\\" DEFAULT 'india'::\\"text\\" NOT NULL,\n    \\"offered_make\\" \\"text\\",\n    \\"source_price\\" numeric,\n    \\"source_currency\\" \\"text\\" DEFAULT 'USD'::\\"text\\" NOT NULL,\n    \\"availability\\" \\"text\\" DEFAULT 'available'::\\"text\\" NOT NULL,\n    \\"document_status\\" \\"text\\" DEFAULT 'pending'::\\"text\\" NOT NULL,\n    \\"remark\\" \\"text\\",\n    \\"is_selected\\" boolean DEFAULT false NOT NULL,\n    \\"confidence\\" numeric,\n    \\"parser_result_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"moq\\" \\"text\\",\n    \\"packing\\" \\"text\\",\n    \\"lead_time\\" \\"text\\",\n    \\"origin\\" \\"text\\",\n    \\"supplier\\" \\"text\\",\n    \\"specification\\" \\"text\\",\n    \\"margin_pct\\" numeric,\n    \\"selling_price\\" numeric,\n    \\"selling_currency\\" \\"text\\"\n)","--\n-- Name: crm_inquiry_timeline; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_inquiry_timeline\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\" NOT NULL,\n    \\"event_type\\" \\"text\\" NOT NULL,\n    \\"event_title\\" \\"text\\" NOT NULL,\n    \\"event_description\\" \\"text\\",\n    \\"old_value\\" \\"text\\",\n    \\"new_value\\" \\"text\\",\n    \\"related_action_id\\" \\"uuid\\",\n    \\"related_activity_id\\" \\"uuid\\",\n    \\"related_email_id\\" \\"uuid\\",\n    \\"performed_by\\" \\"uuid\\",\n    \\"event_timestamp\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"crm_inquiry_timeline_event_type_check\\" CHECK ((\\"event_type\\" = ANY (ARRAY['created'::\\"text\\", 'status_changed'::\\"text\\", 'email_sent'::\\"text\\", 'email_received'::\\"text\\", 'action_performed'::\\"text\\", 'activity_logged'::\\"text\\", 'document_sent'::\\"text\\", 'follow_up_created'::\\"text\\", 'follow_up_completed'::\\"text\\", 'assigned'::\\"text\\", 'note_added'::\\"text\\"])))\n)","--\