uuid\\"() NOT NULL,\n    \\"stage_name\\" \\"text\\" NOT NULL,\n    \\"stage_order\\" integer NOT NULL,\n    \\"color\\" \\"text\\" DEFAULT '#3B82F6'::\\"text\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"()\n)","--\n-- Name: crm_product_documents; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_product_documents\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\",\n    \\"product_name\\" \\"text\\",\n    \\"make\\" \\"text\\",\n    \\"document_type\\" \\"text\\",\n    \\"original_file_name\\" \\"text\\",\n    \\"display_file_name\\" \\"text\\",\n    \\"storage_bucket\\" \\"text\\" DEFAULT 'crm-documents'::\\"text\\",\n    \\"storage_path\\" \\"text\\" NOT NULL,\n    \\"source_gmail_message_id\\" \\"text\\",\n    \\"source_gmail_thread_id\\" \\"text\\",\n    \\"source_email_subject\\" \\"text\\",\n    \\"uploaded_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"crm_product_documents_document_type_check\\" CHECK ((\\"document_type\\" = ANY (ARRAY['COA'::\\"text\\", 'MSDS'::\\"text\\", 'MHD'::\\"text\\", 'TDS'::\\"text\\", 'SPEC'::\\"text\\", 'COC'::\\"text\\", 'GMP'::\\"text\\", 'ISO'::\\"text\\", 'DMF'::\\"text\\", 'OTHER'::\\"text\\"])))\n)","--\n-- Name: crm_quick_actions_log; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_quick_actions_log\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\" NOT NULL,\n    \\"contact_id\\" \\"uuid\\",\n    \\"action_type\\" \\"text\\" NOT NULL,\n    \\"action_label\\" \\"text\\" NOT NULL,\n    \\"email_sent\\" boolean DEFAULT false,\n    \\"email_to\\" \\"text\\",\n    \\"email_subject\\" \\"text\\",\n    \\"email_body\\" \\"text\\",\n    \\"template_used\\" \\"uuid\\",\n    \\"documents_attached\\" \\"text\\"[],\n    \\"old_status\\" \\"text\\",\n    \\"new_status\\" \\"text\\",\n    \\"status_updated\\" boolean DEFAULT false,\n    \\"follow_up_created\\" boolean DEFAULT false,\n    \\"follow_up_date\\" timestamp with time zone,\n    \\"follow_up_reminder_id\\" \\"uuid\\",\n    \\"call_outcome\\" \\"text\\",\n    \\"meeting_outcome\\" \\"text\\",\n    \\"notes\\" \\"text\\",\n    \\"performed_by\\" \\"uuid\\" NOT NULL,\n    \\"performed_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"duration_seconds\\" integer,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"crm_quick_actions_log_action_type_check\\" CHECK ((\\"action_type\\" = ANY (ARRAY['send_price'::\\"text\\", 'send_coa'::\\"text\\", 'send_msds'::\\"text\\", 'send_sample'::\\"text\\", 'follow_up'::\\"text\\", 'send_agency_letter'::\\"text\\", 'send_delivery_update'::\\"text\\", 'log_call'::\\"text\\", 'log_meeting'::\\"text\\", 'log_whatsapp'::\\"text\\", 'add_note'::\\"text\\"])))\n)","--\n-- Name: crm_quotation_items; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_quotation_items\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"quotation_id\\" \\"uuid\\" NOT NULL,\n    \\"product_id\\" \\"uuid\\",\n    \\"product_name\\" \\"text\\" NOT NULL,\n    \\"quantity\\" numeric NOT NULL,\n    \\"unit_price\\" numeric NOT NULL,\n    \\"tax_rate\\" numeric DEFAULT 0,\n    \\"discount_percent\\" numeric DEFAULT 0,\n    \\"line_total\\" numeric GENERATED ALWAYS AS ((((\\"quantity\\" * \\"unit_price\\") * ((1)::numeric - (\\"discount_percent\\" / (100)::numeric))) * ((1)::numeric + (\\"tax_rate\\" / (100)::numeric)))) STORED,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"crm_quotation_items_discount_percent_check\\" CHECK (((\\"discount_percent\\" >= (0)::numeric) AND (\\"discount_percent\\" <= (100)::numeric))),\n    CONSTRAINT \\"crm_quotation_items_quantity_check\\" CHECK ((\\"quantity\\" > (0)::numeric)),\n    CONSTRAINT \\"crm_quotation_items_tax_rate_check\\" CHECK ((\\"tax_rate\\" >= (0)::numeric)),\n    CONSTRAINT \\"crm_quotation_items_unit_price_check\\" CHECK ((\\"unit_price\\" >= (0)::numeric))\n)","--\n-- Name: crm_quotations; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_quotations\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"quotation_number\\" \\"text\\" NOT NULL,\n    \\"lead_id\\" \\"uuid\\",\n    \\"customer_id\\" \\"uuid\\",\n    \\"quotation_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"valid_until\\" \\"date\\" NOT NULL,\n    \\"subtotal\\" numeric DEFAULT 0 NOT NULL,\n    \\"tax_amount\\" numeric DEFAULT 0 NOT NULL,\n    \\"discount_amount\\" numeric DEFAULT 0,\n    \\"total_amount\\" numeric DEFAULT 0 NOT NULL,\n    \\"status\\" \\"text\\" DEFAULT 'draft'::\\"text\\" NOT NULL,\n    \\"notes\\" \\"text\\",\n    \\"terms_conditions\\" \\"text\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"at_least_one_entity\\" CHECK (((\\"lead_id\\" IS NOT NULL) OR (\\"customer_id\\" IS NOT NULL))),\n    CONSTRAINT \\"crm_quotations_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['draft'::\\"text\\", 'sent'::\\"text\\", 'accepted'::\\"text\\", 'rejected'::\\"text\\", 'expired'::\\"text\\"])))\n)","--\n-- Name: crm_reminders; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_reminders\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\",\n    \\"reminder_type\\" \\"text\\" NOT NULL,\n    \\"title\\" \\"text\\" NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"due_date\\" timestamp with time zone NOT NULL,\n    \\"reminder_date\\" timestamp with time zone,\n    \\"is_completed\\" boolean DEFAULT false,\n    \\"completed_at\\" timestamp with time zone,\n    \\"complet