e\\" \\"date\\",\n    \\"notes\\" \\"text\\",\n    \\"status\\" \\"public\\".\\"sales_order_status\\" DEFAULT 'draft'::\\"public\\".\\"sales_order_status\\" NOT NULL,\n    \\"subtotal_amount\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"tax_amount\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"total_amount\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"created_by\\" \\"uuid\\" NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"approved_by\\" \\"uuid\\",\n    \\"approved_at\\" timestamp with time zone,\n    \\"rejected_by\\" \\"uuid\\",\n    \\"rejected_at\\" timestamp with time zone,\n    \\"rejection_reason\\" \\"text\\",\n    \\"is_archived\\" boolean DEFAULT false,\n    \\"archived_at\\" timestamp with time zone,\n    \\"archived_by\\" \\"uuid\\",\n    \\"archive_reason\\" \\"text\\",\n    \\"currency\\" \\"text\\" DEFAULT 'IDR'::\\"text\\",\n    \\"advance_payment_amount\\" numeric(18,2) DEFAULT 0,\n    \\"advance_payment_status\\" character varying(20) DEFAULT 'none'::character varying,\n    \\"company_snapshot\\" \\"jsonb\\",\n    \\"commercial_usd_to_idr_rate\\" numeric(18,6),\n    \\"inquiry_id\\" \\"uuid\\",\n    CONSTRAINT \\"sales_orders_advance_payment_status_check\\" CHECK (((\\"advance_payment_status\\")::\\"text\\" = ANY ((ARRAY['none'::character varying, 'partial'::character varying, 'full'::character varying])::\\"text\\"[]))),\n    CONSTRAINT \\"sales_orders_commercial_usd_to_idr_rate_check\\" CHECK (((\\"commercial_usd_to_idr_rate\\" IS NULL) OR (\\"commercial_usd_to_idr_rate\\" > (0)::numeric))),\n    CONSTRAINT \\"sales_orders_currency_check\\" CHECK ((\\"currency\\" = ANY (ARRAY['USD'::\\"text\\", 'IDR'::\\"text\\"]))),\n    CONSTRAINT \\"valid_amounts\\" CHECK (((\\"subtotal_amount\\" >= (0)::numeric) AND (\\"tax_amount\\" >= (0)::numeric) AND (\\"total_amount\\" >= (0)::numeric))),\n    CONSTRAINT \\"valid_customer_po_number\\" CHECK ((\\"length\\"(TRIM(BOTH FROM \\"customer_po_number\\")) > 0))\n)","--\n-- Name: COLUMN \\"sales_orders\\".\\"currency\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"sales_orders\\".\\"currency\\" IS 'Currency for the sales order: USD or IDR'","--\n-- Name: COLUMN \\"sales_orders\\".\\"commercial_usd_to_idr_rate\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"sales_orders\\".\\"commercial_usd_to_idr_rate\\" IS 'Historical USD to IDR rate used for this order commercial agreement; never recalculated.'","--\n-- Name: COLUMN \\"sales_orders\\".\\"inquiry_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"sales_orders\\".\\"inquiry_id\\" IS 'Optional CRM source inquiry; populated only for an explicit future CRM-to-SO creation.'","--\n-- Name: voucher_allocations; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"voucher_allocations\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"voucher_type\\" character varying(20) NOT NULL,\n    \\"receipt_voucher_id\\" \\"uuid\\",\n    \\"payment_voucher_id\\" \\"uuid\\",\n    \\"sales_invoice_id\\" \\"uuid\\",\n    \\"purchase_invoice_id\\" \\"uuid\\",\n    \\"allocated_amount\\" numeric(18,2) NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"sales_order_id\\" \\"uuid\\",\n    \\"allocated_currency\\" character varying(8) DEFAULT 'IDR'::character varying,\n    \\"finance_expense_id\\" \\"uuid\\",\n    \\"payment_kind\\" \\"text\\" DEFAULT 'supplier'::\\"text\\" NOT NULL,\n    CONSTRAINT \\"voucher_allocations_check\\" CHECK (((((\\"voucher_type\\")::\\"text\\" = 'receipt'::\\"text\\") AND (\\"receipt_voucher_id\\" IS NOT NULL) AND (\\"sales_invoice_id\\" IS NOT NULL)) OR (((\\"voucher_type\\")::\\"text\\" = 'payment'::\\"text\\") AND (\\"payment_voucher_id\\" IS NOT NULL) AND (\\"purchase_invoice_id\\" IS NOT NULL)) OR (((\\"voucher_type\\")::\\"text\\" = 'payment'::\\"text\\") AND (\\"payment_voucher_id\\" IS NOT NULL) AND (\\"finance_expense_id\\" IS NOT NULL)))),\n    CONSTRAINT \\"voucher_allocations_payment_kind_check\\" CHECK ((\\"payment_kind\\" = ANY (ARRAY['supplier'::\\"text\\", 'pph23'::\\"text\\"]))),\n    CONSTRAINT \\"voucher_allocations_voucher_type_check\\" CHECK (((\\"voucher_type\\")::\\"text\\" = ANY ((ARRAY['receipt'::character varying, 'payment'::character varying])::\\"text\\"[])))\n)","--\n-- Name: customer_advance_balances; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"customer_advance_balances\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"c\\".\\"id\\" AS \\"customer_id\\",\n    \\"c\\".\\"company_name\\",\n    COALESCE(\\"sum\\"(\\"va\\".\\"allocated_amount\\"), (0)::numeric) AS \\"total_advances\\",\n    \\"count\\"(DISTINCT \\"va\\".\\"sales_order_id\\") AS \\"orders_with_advance\\"\n   FROM ((\\"public\\".\\"customers\\" \\"c\\"\n     LEFT JOIN \\"public\\".\\"sales_orders\\" \\"so\\" ON ((\\"so\\".\\"customer_id\\" = \\"c\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"voucher_allocations\\" \\"va\\" ON (((\\"va\\".\\"sales_order_id\\" = \\"so\\".\\"id\\") AND ((\\"va\\".\\"voucher_type\\")::\\"text\\" = 'receipt'::\\"text\\"))))\n  WHERE (\\"va\\".\\"sales_order_id\\" IS NOT NULL)\n  GROUP BY \\"c\\".\\"id\\", \\"c\\".\\"company_name\\"","--\n-- Name: VIEW \\"customer_advance_balances\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON VIEW \\"public\\".\\"customer_advance_balances\\" IS 'Security: Converted to SECURITY INVOKER - executes with caller permissions'","--\n-- Name: customer_assignments; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"customer_assignments\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"customer_id\\" \\"uuid\\" NOT NULL,\n    \\"sales_member_id\\" \\"uuid\\" NOT NULL,\n    \\"assigned_at\\" timestamp with time zone DEFAULT \\"now