ase_type\\" IS 'Type of purchase: inventory (stock), fixed_asset, expense, or import'","--\n-- Name: COLUMN \\"purchase_invoices\\".\\"requires_faktur_pajak\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"purchase_invoices\\".\\"requires_faktur_pajak\\" IS 'True if supplier is PKP and Faktur Pajak is required'","--\n-- Name: suppliers; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"suppliers\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"supplier_code\\" character varying(50),\n    \\"company_name\\" character varying(255) NOT NULL,\n    \\"contact_person\\" character varying(255),\n    \\"email\\" character varying(255),\n    \\"phone\\" character varying(50),\n    \\"address\\" \\"text\\",\n    \\"city\\" character varying(100),\n    \\"country\\" character varying(100) DEFAULT 'Indonesia'::character varying,\n    \\"npwp\\" character varying(30),\n    \\"pkp_status\\" boolean DEFAULT false,\n    \\"payment_terms_days\\" integer DEFAULT 30,\n    \\"bank_name\\" character varying(100),\n    \\"bank_account_number\\" character varying(50),\n    \\"bank_account_name\\" character varying(255),\n    \\"notes\\" \\"text\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"postal_code\\" character varying(20),\n    \\"default_expense_category\\" character varying(100),\n    \\"default_pph_code_id\\" \\"uuid\\",\n    \\"tax_preference\\" character varying(20) DEFAULT 'none'::character varying,\n    \\"supplier_type\\" character varying(50),\n    CONSTRAINT \\"suppliers_tax_preference_check\\" CHECK (((\\"tax_preference\\")::\\"text\\" = ANY ((ARRAY['none'::character varying, 'ppn_only'::character varying, 'ppn_pph'::character varying, 'pph_only'::character varying])::\\"text\\"[])))\n)","--\n-- Name: COLUMN 