xt\\") OR (\\"e\\".\\"reason\\" ~~* '%without an accrued payable%'::\\"text\\")) THEN 'Historical accounting decision required'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%multiple typed%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no provable active journal%'::\\"text\\")) THEN 'Manual relink required'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%Approved expense has no active journal%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%Journal metadata cannot be derived%'::\\"text\\")) THEN 'Missing source document'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%No unique authoritative relationship%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%metadata conflicts%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%missing Faktur Pajak%'::\\"text\\")) THEN 'Manual edit required'::\\"text\\"\n                    ELSE 'Investigate further'::\\"text\\"\n                END AS \\"classification\\"\n           FROM \\"public\\".\\"finance_historical_repair_exceptions\\" \\"e\\"\n          WHERE (\\"e\\".\\"status\\" = 'manual_review'::\\"text\\")\n        ), \\"details\\" AS (\n         SELECT \\"e\\".\\"run_id\\",\n            \\"e\\".\\"document_type\\",\n            COALESCE(\\"e\\".\\"document_number\\", NULLIF(\\"bsl\\".\\"reference\\", ''::\\"text\\")) AS \\"document_number\\",\n            \\"e\\".\\"document_id\\" AS \\"database_id\\",\n            COALESCE(\\"fe\\".\\"expense_date\\", \\"rv\\".\\"voucher_date\\", \\"pv\\".\\"voucher_date\\", \\"ft\\".\\"transfer_date\\", \\"l\\".\\"loan_date\\", \\"lt\\".\\"transaction_date\\", \\"cc\\".\\"voucher_date\\", \\"pc\\".\\"transaction_date\\", \\"tp\\".\\"payment_date\\", \\"si\\".\\"invoice_date\\", \\"pi\\".\\"invoice_date\\", \\"je\\".\\"entry_date\\", \\"bsl\\".\\"transaction_date\\") AS \\"document_date\\",\n            COALESCE(\\"fe\\".\\"amount\\", \\"rv\\".\\"amount\\", \\"pv\\".\\"amount\\", \\"ft\\".\\"amount\\", \\"l\\".\\"principal_amount\\", \\"lt\\".