             LEFT JOIN \\"public\\".\\"suppliers\\" \\"purchase_supplier\\" ON ((\\"purchase_supplier\\".\\"id\\" = \\"pi\\".\\"supplier_id\\")))\n             LEFT JOIN \\"public\\".\\"bank_accounts\\" \\"fba\\" ON ((\\"fba\\".\\"id\\" = \\"ft\\".\\"from_bank_account_id\\")))\n             LEFT JOIN \\"public\\".\\"bank_accounts\\" \\"tba\\" ON ((\\"tba\\".\\"id\\" = \\"ft\\".\\"to_bank_account_id\\")))\n             LEFT JOIN \\"public\\".\\"bank_accounts\\" \\"ba\\" ON ((\\"ba\\".\\"id\\" = COALESCE(\\"fe\\".\\"bank_account_id\\", \\"rv\\".\\"bank_account_id\\", \\"pv\\".\\"bank_account_id\\", \\"l\\".\\"bank_account_id\\", \\"lt\\".\\"bank_account_id\\", \\"cc\\".\\"bank_account_id\\", \\"pc\\".\\"bank_account_id\\", \\"tp\\".\\"bank_account_id\\", \\"bsl\\".\\"bank_account_id\\"))))\n             LEFT JOIN LATERAL ( SELECT \\"j\\".\\"entry_number\\"\n                   FROM \\"public\\".\\"journal_entries\\" \\"j\\"\n                  WHERE (((\\"e\\".\\"document_type\\" = 'journal'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"je\\".\\"id\\")) OR ((\\"e\\".\\"document_type\\" = 'expense'::\\"text\\") AND ((\\"j\\".\\"source_module\\")::\\"text\\" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::\\"text\\"[])) AND ((\\"j\\".\\"reference_id\\" = \\"fe\\".\\"id\\") OR ((\\"j\\".\\"reference_number\\")::\\"text\\" = ('EXP-'::\\"text\\" || (\\"fe\\".\\"id\\")::\\"text\\")))) OR ((\\"e\\".\\"document_type\\" = 'receipt'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"rv\\".\\"journal_entry_id\\")) OR ((\\"e\\".\\"document_type\\" = 'payment'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"pv\\".\\"journal_entry_id\\")) OR ((\\"e\\".\\"document_type\\" = 'fund_transfer'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"ft\\".\\"journal_entry_id\\")) OR ((\\"e\\".\\"document_type\\" = 'loan'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"l\\".\\"journal_entry_id\\")) OR ((\\"e\\".\\"document_type\\" = ANY (ARRAY['loan_transaction'::\\"text\\", 'loan_repayment'::\\"text\\"])) AND (\\"j\\".\\"id\\" = \\"lt\\".\\"journal_entry_id\\")) OR ((\\"e\\".\\"document_type\\" = 'capital_contribution'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"cc\\".\\"journal_entry_id\\")) OR ((\\"e\\".\\"document_type\\" = 'petty_cash'::\\"text\\") AND ((\\"j\\".\\"source_module\\")::\\"text\\" = 'petty_cash'::\\"text\\") AND (\\"j\\".\\"reference_id\\" = \\"pc\\".\\"id\\")) OR ((\\"e\\".\\"document_type\\" = 'tax_payment'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"tp\\".\\"journal_entry_id\\")) OR ((\\"e\\".\\"document_type\\" = 'sales_invoice'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"si\\".\\"journal_entry_id\\")) OR ((\\"e\\".\\"document_type\\" = 'purchase_invoice'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"pi\\".\\"journal_entry_id\\")) OR ((\\"e\\".\\"document_type\\" = 'bank_reconciliation'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"bsl\\".\\"matched_entry_id\\")))\n                  ORDER BY \\"j\\".\\"is_posted\\" DESC, COALESCE(\\"j\\".\\"is_reversed\\", false), \\"j\\".\\"created_at\\" DESC\n                 LIMIT 1) \\"source_je\\" ON (true))\n        )\n SELECT \\"run_id\\",\n    \\"document_type\\",\n    COALESCE(\\"document_number\\", '(none)'::\\"text\\") AS \\"document_number\\",\n    \\"database_id\\",\n    \\"document_date\\" AS \\"date\\",\n    \\"amount\\",\n    COALESCE(\\"currency\\", 'Unknown'::\\"text\\") AS \\"currency\\",\n    \\"customer_supplier\\",\n    \\"bank_account\\",\n    \\"journal_number\\",\n    \\"array_to_string\\"(\\"inconsistent_fields\\", ', '::\\"text\\") AS \\"exact_problem_fields\\",\n    \\"reason\\" AS \\"exact_problem\\",\n    \\"reason\\" AS \\"why_cannot_repair_automatically\\",\n    \\"classification\\",\n        CASE \\"classification\\"\n            WHEN 'Historical accounting decision required'::\\"text\\" THEN \\"manual_information_required\\"\n            WHEN 'Manual relink required'::\\"text\\" THEN \\"manual_information_required\\"\n            WHEN 'Missing source document'::\\"text\\" THEN \\"manual_information_required\\"\n            WHEN 'Manual edit required'::\\"text\\" THEN \\"manual_information_required\\"\n            ELSE 'Investigate the source document, journal, bank line, and audit trail before making any change'::\\"text\\"\n        END AS \\"recommended_action\\",\n    false AS \\"safe_to_delete_and_recreate\\",\n    'Keep — deletion/recreation could remove audit evidence or rewrite posted history; resolve through an authorised manual correction'::\\"text\\" AS \\"disposition\\",\n    \\"created_at\\"\n   FROM \\"details\\"","--\n-- Name: finance_historical_repair_items; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"finance_historical_repair_items\\" (\n    \\"id\\" bigint NOT NULL,\n    \\"run_id\\" \\"uuid\\" NOT NULL,\n    \\"document_type\\" \\"text\\" NOT NULL,\n    \\"document_id\\" \\"uuid\\" NOT NULL,\n    \\"document_number\\" \\"text\\",\n    \\"repaired_fields\\" \\"text\\"[] NOT NULL,\n    \\"old_metadata\\" \\"jsonb\\" NOT NULL,\n    \\"new_metadata\\" \\"jsonb\\" NOT NULL,\n    \\"repair_reason\\" \\"text\\" NOT NULL,\n    \\"repaired_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL\n)","--\n-- Name: finance_historical_repair_verification; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"finance_historical_repair_verification\\" WITH (\\"security_invoker\\"='true') AS\n WITH \\"repaired\\" AS (\n         SELECT \\"finance_historical_repair_items\\".\\"run_id\\",\n            \\"finance_historical_repair_items\\".\\"document_type\\",\n            \\"finance_historical_repair_items\\".\\"document_id\\",\n            \\"bool_or\\"(((\\"finance_historical_repair_items\\".\\"repair_reason\\" ~~* '%Bank Reconciliation%'::\\"text\\") OR (\\"finance_historical_repair_items\\".\\"document_type\\" = 'bank_reconciliation'::\\"text\\"))) AS \\"reconciliation_expected\\"\n           FROM \\"public\\".\\"finance_historical_repair_items\\"\n          GROUP BY \\"finance_historical_repair_items\\".\\"run_i