            \\"r\\".\\"document_id\\",\n            \\"r\\".\\"reconciliation_expected\\",\n            \\"je\\".\\"entry_number\\",\n            true,\n            ((\\"je\\".\\"is_posted\\" = true) AND (COALESCE(\\"je\\".\\"is_reversed\\", false) = false)),\n                CASE\n                    WHEN ((\\"je\\".\\"is_posted\\" = true) AND (COALESCE(\\"je\\".\\"is_reversed\\", false) = false)) THEN \\"je\\".\\"id\\"\n                    ELSE NULL::\\"uuid\\"\n                END AS \\"case\\",\n            (EXISTS ( SELECT 1\n                   FROM (\\"public\\".\\"journal_entry_lines\\" \\"l\\"\n                     JOIN \\"public\\".\\"bank_accounts\\" \\"ba\\" ON ((\\"ba\\".\\"coa_id\\" = \\"l\\".\\"account_id\\")))\n                  WHERE (\\"l\\".\\"journal_entry_id\\" = \\"je\\".\\"id\\"))) AS \\"exists\\",\n            false,\n            ( SELECT \\"count\\"(*) AS \\"count\\"\n                   FROM \\"public\\".\\"bank_statement_lines\\" \\"b\\"\n                  WHERE (\\"b\\".\\"matched_entry_id\\" = \\"je\\".\\"id\\")) AS \\"count\\"\n           FROM (\\"repaired\\" \\"r\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON (((\\"r\\".\\"document_type\\" = 'journal'::\\"text\\") AND (\\"je\\".\\"id\\" = \\"r\\".\\"document_id\\"))))\n        UNION ALL\n         SELECT \\"r\\".\\"run_id\\",\n            \\"r\\".\\"document_type\\",\n            \\"r\\".\\"document_id\\",\n            \\"r\\".\\"reconciliation_expected\\",\n            \\"b\\".\\"reference\\",\n            true,\n            (\\"b\\".\\"reconciliation_status\\" = ANY (ARRAY['matched'::\\"text\\", 'recorded'::\\"text\\"])),\n                CASE\n                    WHEN ((\\"je\\".\\"is_posted\\" = true) AND (COALESCE(\\"je\\".\\"is_reversed\\", false) = false)) THEN \\"je\\".\\"id\\"\n                    ELSE NULL::\\"uuid\\"\n                END AS \\"case\\",\n            true,\n            false,\n            (1)::bigint AS \\"int8\\"\n           FROM ((\\"repaired\\" \\"r\\"\n             JOIN \\"public\\".\\"bank_statement_lines\\" \\"b\\" ON (((\\"r\\".\\"document_type\\" = 'bank_reconciliation'::\\"text\\") AND (\\"b\\".\\"id\\" = \\"r\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"b\\".\\"matched_entry_id\\")))\n        ), \\"checked\\" AS (\n         SELECT \\"x\\".\\"run_id\\",\n            \\"x\\".\\"document_type\\",\n            \\"x\\".\\"document_id\\",\n            \\"x\\".\\"reconciliation_expected\\",\n            \\"x\\".\\"document_number\\",\n            \\"x\\".\\"source_exists\\",\n            \\"x\\".\\"posting_expected\\",\n            \\"x\\".\\"active_journal_id\\",\n            \\"x\\".\\"bank_expected\\",\n            \\"x\\".\\"party_expected\\",\n            \\"x\\".\\"bank_link_count\\",\n            ((NOT \\"x\\".\\"posting_expected\\") OR (\\"x\\".\\"active_journal_id\\" IS NOT NULL)) AS \\"journal_ok\\",\n            ((NOT \\"x\\".\\"posting_expected\\") OR (EXISTS ( SELECT 1\n                   FROM \\"public\\".\\"journal_entry_lines\\" \\"l\\"\n                  WHERE (\\"l\\".\\"journal_entry_id\\" = \\"x\\".\\"active_journal_id\\")))) AS \\"lines_ok\\",\n            ((NOT \\"x\\".\\"bank_expected\\") OR (NOT \\"x\\".\\"posting_expected\\") OR (EXISTS ( SELECT 1\n                   FROM (\\"public\\".\\"journal_entry_lines\\" \\"l\\"\n                     JOIN \\"public\\".\\"bank_accounts\\" \\"ba\\" ON ((\\"ba\\".\\"coa_id\\" = \\"l\\".\\"account_id\\")))\n                  WHERE (\\"l\\".\\"journal_entry_id\\" = \\"x\\".\\"active_journal_id\\")))) AS \\"bank_ok\\",\n            ((NOT \\"x\\".\\"reconciliation_expected\\") OR (\\"x\\".\\"bank_link_count\\" > 0)) AS \\"reconciliation_ok\\"\n           FROM \\"resolved\\" \\"x\\"\n        )\n SELECT \\"run_id\\",\n    \\"document_number\\",\n    \\"document_type\\",\n    \\"document_id\\" AS \\"database_id\\",\n    \\"source_exists\\" AS \\"source_module\\",\n    \\"journal_ok\\" AS \\"journal_register\\",\n    \\"journal_ok\\" AS \\"journal_viewer\\",\n    (\\"journal_ok\\" AND \\"lines_ok\\") AS \\"account_ledger\\",\n    \\"bank_ok\\" AS \\"bank_ledger\\",\n    ((NOT \\"party_expected\\") OR (NOT \\"posting_expected\\") OR (\\"journal_ok\\" AND \\"lines_ok\\")) AS \\"party_ledger\\",\n    (\\"journal_ok\\" AND \\"lines_ok\\") AS \\"trial_balance\\",\n    (\\"journal_ok\\" AND \\"lines_ok\\") AS \\"balance_sheet\\",\n    (\\"journal_ok\\" AND \\"lines_ok\\") AS \\"profit_and_loss\\",\n    (\\"journal_ok\\" AND \\"lines_ok\\") AS \\"dashboard\\",\n    \\"reconciliation_ok\\" AS \\"bank_reconciliation\\",\n    (\\"source_exists\\" AND \\"journal_ok\\" AND \\"lines_ok\\" AND \\"bank_ok\\" AND ((NOT \\"party_expected\\") OR (NOT \\"posting_expected\\") OR (\\"journal_ok\\" AND \\"lines_ok\\")) AND \\"reconciliation_ok\\") AS \\"verification_passed\\"\n   FROM \\"checked\\"","--\n-- Name: finance_historical_repair_verification_failures; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"finance_historical_repair_verification_failures\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"run_id\\",\n    \\"document_number\\",\n    \\"document_type\\",\n    \\"database_id\\",\n    \\"source_module\\",\n    \\"journal_register\\",\n    \\"journal_viewer\\",\n    \\"account_ledger\\",\n    \\"bank_ledger\\",\n    \\"party_ledger\\",\n    \\"trial_balance\\",\n    \\"balance_sheet\\",\n    \\"profit_and_loss\\",\n    \\"dashboard\\",\n    \\"bank_reconciliation\\",\n    \\"verification_passed\\"\n   FROM \\"public\\".\\"finance_historical_repair_verification\\"\n  WHERE (NOT \\"verification_passed\\")","--\n-- Name: finance_exception_accountant_review_dashboard; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"finance_exception_accountant_review_dashboard\\" WITH (\\"security_invoker\\"='true') AS\n WITH \\"unresolved\\" AS (\n         SELECT ('exception:'::\\"text\\" || (\\"e\\".\\"id\\")::\\"text\\") AS \\"row_id\\",\n            \\"e\\".\\"id\\" AS \\"exception_id\\",\n            \\"e\\".\\"run_id\\",\n            \\"e\\".\\"document_type\\",\n            \\"e\\".\\"document_id\\",\n            \\"d\\".\\"date\\",\n            \\"d\\".\\"document_number\\" AS \\"voucher_number\\",\n            \\"d\\".\\"journal_number\\",\n            \\"d\\".\\"amount\\",\n            \\"d\\".\\"currency\\",\n            \\"d\\".\\"bank_account\\" AS \\"bank\\",\n            \\"d\\".\\"customer_supplier\\",\n            \\"d\\".\\"classification\\",\n            \\"e\\".\\"reason\\",\n            \\"e\\".\\"manual_information_required\\",\n            \\"d\\".\\"recommended_action\\",\n            \\"e\\".\\"inconsistent_fields\\"\n           FROM (\\"public\\".\\"finance_historical_repair_exceptions\\" \\"e\\"\n             JOIN \\"public\\".\\"finance_historical_repair_exception_details\\" \\"d\\" ON (((\\"d\\".\\"run_id\\" = \\"e\\".\\"run_id\\") AND (\\"d\\".\\"document_type\\" = \\"e\\".\\"document_type\\") AND (\\"d\\".\\"database_id\\" = \\"e\\".\\"document_id\\") AND (\\"d\\".\\"exact_problem\\" = \\"e\\".\\"reason\\"))))\n          WHERE (\\"e\\".\\"status\\" = 'manual_review'::\\"text\\")\n        ), \\"enriched\\" AS (\n         SELECT \\"u\\".\\"row_id\\",\n            \\"u\\".\\"exception_id\\",\n            \\"u\\".\\"run_id\\",\n            \\"u\\".\\"document_type\\",\n            \\"u\\".\\"document_id\\",\n            \\"u\\".\\"date\\",\n            \\"u\\".\\"voucher_number\\",\n            \\"u\\".\\"journal_number\\",\n            \\"u\\".\\"amount\\",\n            \\"u\\".\\"currency\\",\n            \\"u\\".\\"bank\\",\n            \\"u\\".\\"customer_supplier\\",\n            \\"u\\".\\"classification\\",\n            \\"u\\".\\"reason\\",\n            \\"u\\".\\"manual_information_required\\",\n            \\"u\\".\\"recommended_action\\",\n            \\"u\\".\\"inconsistent_fields\\",\n            COALESCE(\\"fe\\".\\"expense_category\\", (\\"pc\\".\\"expense_category\\")::\\"text\\", \\"je\\".\\"transaction_category\\", \\"l\\".\\"loan_type\\", (\\"cc\\".\\"contribution_type\\")::\\"text\\", \\"tp\\".\\"tax_type\\", (\\"pi\\".\\"purchase_type\\")::\\"text\\", \\"bsl\\".\\"payment_kind\\") AS \\"current_category\\",\n            COALESCE(\\"fe\\".\\"bank_account_id\\", \\"rv\\".\\"bank_account_id\\", \\"pv\\".\\"bank_account_id\\", \\"l\\".\\"bank_account_id\\", \\"lt\\".\\"bank_account_id\\", \\"cc\\".\\"bank_account_id\\", \\"pc\\".\\"bank_account_id\\", \\"tp\\".\\"bank_account_id\\", \\"bsl\\".\\"bank_account_id\\") AS \\"current_bank_account_id\\",\n            \\"source_je\\".\\"id\\" AS \\"journal_entry_id\\",\n            \\"current_line\\".\\"id\\" AS \\"journal_line_id\\",\n            \\"current_line\\".\\"account_id\\" AS \\"current_account_id\\",\n            \\"concat_ws\\"(' · '::\\"text\\", \\"coa\\".\\"code\\", \\"coa\\".\\"name\\") AS \\"current_gl_account\\",\n            \\"fe\\".\\"exchange_rate\\" AS \\"expense_exchange_rate\\",\n            COALESCE(\\"fe\\".\\"pph_code_id\\", \\"pv\\".\\"pph_code_id\\") AS \\"current_tax_code_id\\",\n            COALESCE(\\"fe\\".\\"payment_method\\", \\"rv\\".\\"payment_method\\", \\"pv\\".\\"payment_method\\", (\\"bsl\\".\\"payment_kind\\")::character varying) AS \\"current_payment_type\\",\n            \\"source_je\\".\\"source_module\\" AS \\"current_document_classification\\",\n            COALESCE(\\"si\\".\\"faktur_pajak_number\\", \\"pi\\".\\"faktur_pajak_number\\") AS \\"current_faktur_pajak_number\\"\n           FROM ((((((((((((((((\\"unresolved\\" \\"u\\"\n             LEFT JOIN \\"public\\".\\"finance_expenses\\" \\"fe\\" ON (((\\"u\\".\\"document_type\\" = 'expense'::\\"text\\") AND (\\"fe\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"receipt_vouchers\\" \\"rv\\" ON (((\\"u\\".\\"document_type\\" = 'receipt'::\\"text\\") AND (\\"rv\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"payment_vouchers\\" \\"pv\\" ON (((\\"u\\".\\"document_type\\" = 'payment'::\\"text\\") AND (\\"pv\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"fund_transfers\\" \\"ft\\" ON (((\\"u\\".\\"document_type\\" = 'fund_transfer'::\\"text\\") AND (\\"ft\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"loans\\" \\"l\\" ON (((\\"u\\".\\"document_type\\" = 'loan'::\\"text\\") AND (\\"l\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"loan_transactions\\" \\"lt\\" ON (((\\"u\\".\\"document_type\\" = ANY (ARRAY['loan_transaction'::\\"text\\", 'loan_repayment'::\\"text\\"])) AND (\\"lt\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"capital_contributions\\" \\"cc\\" ON (((\\"u\\".\\"document_type\\" = 'capital_contribution'::\\"text\\") AND (\\"cc\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"petty_cash_transactions\\" \\"pc\\" ON (((\\"u\\".\\"document_type\\" = 'petty_cash'::\\"text\\") AND (\\"pc\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"tax_payments\\" \\"tp\\" ON (((\\"u\\".\\"document_type\\" = 'tax_payment'::\\"text\\") AND (\\"tp\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"sales_invoices\\" \\"si\\" ON (((\\"u\\".\\"document_type\\" = 'sales_invoice'::\\"text\\") AND (\\"si\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"purchase_invoices\\" \\"pi\\" ON (((\\"u\\".\\"document_type\\" = 'purchase_invoice'::\\"text\\") AND (\\"pi\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON (((\\"u\\".\\"document_type\\" = 'journal'::\\"text\\") AND (\\"je\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"bank_statement_lines\\" \\"bsl\\" ON (((\\"u\\".\\"document_type\\" = 'bank_reconciliation'::\\"text\\") AND (\\"bsl\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN LATERAL ( SELECT \\"j\\".\\"id\\",\n                    \\"j\\".\\"entry_number\\",\n                    \\"j\\".\\"entry_date\\",\n                    \\"j\\".\\"period_id\\",\n                    \\"j\\".\\"source_module\\",\n                    \\"j\\".\\"reference_id\\",\n                    \\"j\\".\\"reference_number\\",\n                    \\"j\\".\\"description\\",\n                    \\"j\\".\\"total_debit\\",\n                    \\"j\\".\\"total_credit\\",\n                    \\"j\\".\\"is_posted\\",\n                    \\"j\\".\\"is_reversed\\",\n                    \\"j\\".\\"reversed_by_id\\",\n                    \\"j\\".\\"posted_by\\",\n                    \\"j\\".\\"posted_at\\",\n                    \\"j\\".\\"created_by\\",\n                    \\"j\\".\\"created_at\\",\n                    \\"j\\".\\"transaction_category\\",\n                    \\"j\\".\\"transaction_currency\\",\n                    \\"j\\".\\"functional_currency\\",\n                    \\"j\\".\\"exchange_rate\\",\n                    \\"j\\".\\"amounts_are_functional\\"\n                   FROM \\"public\\".\\"journal_entries\\" \\"j\\"\n                  WHERE (((\\"u\\".\\"document_type\\" = 'journal'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"u\\".\\"document_id\\")) OR ((\\"u\\".\\"document_type\\" = 'expense'::\\"text\\") AND ((\\"j\\".\\"source_module\\")::\\"text\\" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::\\"text\\"[])) AND ((\\"j\\".\\"reference_id\\" = \\"u\\".\\"document_id\\") OR ((\\"j\\".\\"reference_number\\")::\\"text\\" = ('EXP-'::\\"text\\" || (\\"u\\".\\"document_id\\")::\\"text\\")))) OR ((\\"u\\".\\"document_type\\" = 'receipt'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"rv\\".\\"journal_entry_id\\")) OR ((\\"u\\".\\"document_type\\" = 'payment'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"pv\\".\\"journal_entry_id\\")) OR ((\\"u\\".\\"document_type\\" = 'fund_transfer'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"ft\\".\\"journal_entry_id\\")) OR ((\\"u\\".\\"document_type\\" = 'loan'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"l\\".\\"journal_entry_id\\")) OR ((\\"u\\".\\"document_type\\" = ANY (ARRAY['loan_transaction'::\\"text\\", 'loan_repayment'::\\"text\\"])) AND (\\"j\\".\\"id\\" = \\"lt\\".\\"journal_entry_id\\")) OR ((\\"u\\".\\"document_type\\" = 'capital_contribution'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"cc\\".\\"journal_entry_id\\")) OR ((\\"u\\".\\"document_type\\" = 'petty_cash'::\\"text\\") AND ((\\"j\\".\\"source_module\\")::\\"text\\" = 'petty_cash'::\\"text\\") AND (\\"j\\".\\"reference_id\\" = \\"u\\".\\"document_id\\")) OR ((\\"u\\".\\"document_type\\" = 'tax_payment'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"tp\\".\\"journal_entry_id\\")) OR ((\\"u\\".\\"document_type\\" = 'sales_invoice'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"si\\".\\"journal_entry_id\\")) OR ((\\"u\\".\\"document_type\\" = 'purchase_invoice'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"pi\\".\\"journal_entry_id\\")) OR ((\\"u\\".\\"document_type\\" = 'bank_reconciliation'::\\"text\\") AND (\\"j\\".\\"id\\" = \\"bsl\\".\\"matched_entry_id\\")))\n                  ORDER BY \\"j\\".\\"is_posted\\" DESC, COALESCE(\\"j\\".\\"is_reversed\\", false), \\"j\\".\\"created_at\\" DESC\n                 LIMIT 1) \\"source_je\\" ON (true))\n             LEFT JOIN LATERAL ( SELECT \\"jl\\".\\"id\\",\n                    \\"jl\\".\\"journal_entry_id\\",\n                    \\"jl\\".\\"line_number\\",\n                    \\"jl\\".\\"account_id\\",\n                    \\"jl\\".\\"description\\",\n                    \\"jl\\".\\"debit\\",\n                    \\"jl\\".\\"credit\\",\n                    \\"jl\\".\\"tax_code_id\\",\n                    \\"jl\\".\\"customer_id\\",\n                    \\"jl\\".\\"supplier_id\\",\n                    \\"jl\\".\\"batch_id\\",\n                    \\"jl\\".\\"created_at\\",\n                    \\"jl\\".\\"transaction_currency\\",\n                    \\"jl\\".\\"transaction_debit\\",\n                    \\"jl\\".\\"transaction_credit\\",\n                    \\"jl\\".\\"functional_currency\\",\n                    \\"jl\\".\\"exchange_rate\\"\n                   FROM \\"public\\".\\"journal_entry_lines\\" \\"jl\\"\n                  WHERE (\\"jl\\".\\"journal_entry_id\\" = \\"source_je\\".\\"id\\")\n                  ORDER BY\n                        CASE\n                            WHEN ((\\"u\\".\\"document_type\\" = 'bank_reconciliation'::\\"text\\") AND (((COALESCE(\\"bsl\\".\\"credit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF(\\"jl\\".\\"transaction_debit\\", (0)::numeric), \\"jl\\".\\"debit\\") = \\"bsl\\".\\"credit_amount\\")) OR ((COALESCE(\\"bsl\\".\\"debit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF(\\"jl\\".\\"transaction_credit\\", (0)::numeric), \\"jl\\".\\"credit\\") = \\"bsl\\".\\"debit_amount\\")))) THEN 0\n                            WHEN (\\"jl\\".\\"account_id\\" = COALESCE(\\"l\\".\\"coa_id\\", \\"rv\\".\\"coa_account_id\\", \\"pv\\".\\"coa_account_id\\", \\"fe\\".\\"fixed_asset_account_id\\")) THEN 0\n                            ELSE 1\n                        END, \\"jl\\".\\"line_number\\"\n                 LIMIT 1) \\"current_line\\" ON (true))\n             LEFT JOIN \\"public\\".\\"chart_of_accounts\\" \\"coa\\" ON ((\\"coa\\".\\"id\\" = \\"current_line\\".\\"account_id\\")))\n        ), \\"business_rows\\" AS (\n         SELECT \\"e\\".\\"row_id\\",\n            \\"e\\".\\"exception_id\\",\n            \\"e\\".\\"run_id\\",\n            \\"e\\".\\"document_type\\",\n            \\"e\\".\\"document_id\\",\n            \\"e\\".\\"date\\",\n            \\"e\\".\\"voucher_number\\",\n            \\"e\\".\\"journal_number\\",\n            \\"e\\".\\"amount\\",\n            \\"e\\".\\"currency\\",\n            \\"e\\".\\"bank\\",\n            \\"e\\".\\"customer_supplier\\",\n            \\"e\\".\\"classification\\",\n            \\"e\\".\\"reason\\",\n            \\"e\\".\\"manual_information_required\\",\n            \\"e\\".\\"recommended_action\\",\n            \\"e\\".\\"inconsistent_fields\\",\n            \\"e\\".\\"current_category\\",\n            \\"e\\".\\"current_bank_account_id\\",\n            \\"e\\".\\"journal_entry_id\\",\n            \\"e\\".\\"journal_line_id\\",\n            \\"e\\".\\"current_account_id\\",\n            \\"e\\".\\"current_gl_account\\",\n            \\"e\\".\\"expense_exchange_rate\\",\n            \\"e\\".\\"current_tax_code_id\\",\n            \\"e\\".\\"current_payment_type\\",\n            \\"e\\".\\"current_document_classification\\",\n            \\"e\\".\\"current_faktur_pajak_number\\",\n                CASE\n                    WHEN (\\"e\\".\\"reason\\" ~~* 'No unique authoritative relationship%'::\\"text\\") THEN 'The historical record is missing a confirmed payment method, bank, currency, or exchange rate.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%no historical transaction-date rate%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no authoritative historical rate%'::\\"text\\")) THEN 'The transaction is confirmed as foreign currency, but its original exchange rate is missing.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%USD-source Contra%'::\\"text\\") THEN 'The transfer used an older foreign-currency treatment that cannot be corrected without an accountant decision.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%does not post to this bank account%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%does not use the Expense bank account%'::\\"text\\")) THEN 'The voucher and bank transaction are linked, but the journal uses a different account.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%amount or direction does not match%'::\\"text\\") THEN 'The amount or money-in/money-out direction differs between the bank transaction and journal.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%missing Faktur Pajak%'::\\"text\\") THEN 'A taxed invoice is missing its Faktur Pajak number.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%without an accrued payable%'::\\"text\\") THEN 'A tax payment exists without the earlier tax amount being recorded as payable.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%no active journal%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no provable active journal%'::\\"text\\")) THEN 'The document does not have a confirmed active journal.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%metadata conflicts%'::\\"text\\") THEN 'The voucher details conflict with the linked bank transaction.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%Journal metadata cannot be derived%'::\\"text\\") THEN 'The journal source or classification cannot be confirmed from the historical record.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%no native Loan source document%'::\\"text\\") THEN 'The journal is loan-related, but its original loan document is missing.'::\\"text\\"\n                    ELSE 'The historical record needs an accountant to confirm its correct classification.'::\\"text\\"\n                END AS \\"problem\\",\n                CASE\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%no historical transaction-date rate%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no authoritative historical rate%'::\\"text\\")) THEN 'The application must not guess a historical exchange rate.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%USD-source Contra%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%amount or direction does not match%'::\\"text\\")) THEN 'Correcting it automatically could change the meaning of posted accounting amounts.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%no active journal%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no native Loan source document%'::\\"text\\")) THEN 'No existing source-to-journal relationship proves a safe automatic correction.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%without an accrued payable%'::\\"text\\") THEN 'Only an accountant can confirm whether an accrual or reclassification is appropriate.'::\\"text\\"\n                    ELSE 'More than one correction is possible from the available historical information.'::\\"text\\"\n                END AS \\"why_not_automatic\\"\n           FROM \\"enriched\\" \\"e\\"\n        )\n SELECT \\"business_rows\\".\\"row_id\\",\n    \\"business_rows\\".\\"exception_id\\",\n    \\"business_rows\\".\\"run_id\\",\n    \\"business_rows\\".\\"document_type\\",\n    \\"business_rows\\".\\"document_id\\",\n    \\"business_rows\\".\\"date\\",\n    \\"business_rows\\".\\"voucher_number\\",\n    \\"business_rows\\".\\"journal_number\\",\n    \\"business_rows\\".\\"amount\\",\n    \\"business_rows\\".\\"currency\\",\n    \\"business_rows\\".\\"bank\\",\n    \\"business_rows\\".\\"customer_supplier\\",\n    \\"business_rows\\".\\"current_category\\",\n    \\"business_rows\\".\\"current_gl_account\\",\n    'Needs accountant review'::\\"text\\" AS \\"status\\",\n    \\"business_rows\\".\\"problem\\",\n    \\"business_rows\\".\\"why_not_automatic\\",\n    \\"business_rows\\".\\"recommended_action\\",\n    \\"business_rows\\".\\"current_bank_account_id\\",\n    \\"business_rows\\".\\"journal_entry_id\\",\n    \\"business_rows\\".\\"journal_line_id\\",\n    \\"business_rows\\".\\"current_account_id\\",\n    \\"business_rows\\".\\"current_tax_code_id\\",\n    \\"business_rows\\".\\"current_payment_type\\",\n    \\"business_rows\\".\\"current_document_classification\\",\n    \\"business_rows\\".\\"current_faktur_pajak_number\\",\n    \\"business_rows\\".\\"expense_exchange_rate\\"\n   FROM \\"business_rows\\"\nUNION ALL\n SELECT ((('verification:'::\\"text\\" || \\"vf\\".\\"document_type\\") || ':'::\\"text\\") || (\\"vf\\".\\"database_id\\")::\\"text\\") AS \\"row_id\\",\n    NULL::bigint AS \\"exception_id\\",\n    \\"vf\\".\\"run_id\\",\n    \\"vf\\".\\"document_type\\",\n    \\"vf\\".\\"database_id\\" AS \\"document_id\\",\n    NULL::\\"date\\" AS \\"date\\",\n    COALESCE(\\"vf\\".\\"document_number\\", '(none)'::\\"text\\") AS \\"voucher_number\\",\n    NULL::\\"text\\" AS \\"journal_number\\",\n    NULL::numeric AS \\"amount\\",\n    'Unknown'::\\"text\\" AS \\"currency\\",\n    NULL::\\"text\\" AS \\"bank\\",\n    NULL::\\"text\\" AS \\"customer_supplier\\",\n    NULL::\\"text\\" AS \\"current_category\\",\n    NULL::\\"text\\" AS \\"current_gl_account\\",\n    'Verification failed'::\\"text\\" AS \\"status\\",\n    'A Finance verification check still fails for this record.'::\\"text\\" AS \\"problem\\",\n    'The current Finance data does not yet satisfy every report check.'::\\"text\\" AS \\"why_not_automatic\\",\n    'Review the source document, journal and linked bank transaction, then save the confirmed classifications.'::\\"text\\" AS \\"recommended_action\\",\n    NULL::\\"uuid\\" AS \\"current_bank_account_id\\",\n    NULL::\\"uuid\\" AS \\"journal_entry_id\\",\n    NULL::\\"uuid\\" AS \\"journal_line_id\\",\n    NULL::\\"uuid\\" AS \\"current_account_id\\",\n    NULL::\\"uuid\\" AS \\"current_tax_code_id\\",\n    NULL::\\"text\\" AS \\"current_payment_type\\",\n    NULL::\\"text\\" AS \\"current_document_classification\\",\n    NULL::\\"text\\" AS \\"current_faktur_pajak_number\\",\n    NULL::numeric AS \\"expense_exchange_rate\\"\n   FROM \\"public\\".\\"finance_historical_repair_verification_failures\\" \\"vf\\"\n  WHERE (NOT (EXISTS ( SELECT 1\n           FROM \\"unresolved\\" \\"u\\"\n          WHERE ((\\"u\\".\\"run_id\\" = \\"vf\\".\\"run_id\\") AND (\\"u\\".\\"document_type\\" = \\"vf\\".\\"document_type\\") AND (\\"u\\".\\"document_id\\" = \\"vf\\".\\"database_id\\")))))","--\n-- Name: finance_historical_repair_runs; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"finance_historical_repair_runs\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"started_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"completed_at\\" timestamp with time zone,\n    \\"total_records_scanned\\" bigint DEFAULT 0 NOT NULL,\n    \\"records_repaired\\" bigint DEFAULT 0 NOT NULL,\n    \\"records_partially_repaired\\" bigint DEFAULT 0 NOT NULL,\n    \\"records_manual_review\\" bigint DEFAULT 0 NOT NULL,\n    \\"records_skipped\\" bigint DEFAULT 0 NOT NULL,\n    \\"notes\\" \\"text\\"\n)","--\n-- Name: finance_historical_repair_summary; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"finance_historical_repair_summary\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"id\\" AS \\"run_id\\",\n    \\"started_at\\",\n    \\"completed_at\\",\n    \\"total_records_scanned\\",\n    \\"records_repaired\\",\n    \\"records_partially_repaired\\",\n    \\"records_manual_review\\",\n    \\"records_skipped\\",\n    \\"notes\\"\n   FROM \\"public\\".\\"finance_historical_repair_runs\\"","--\n-- Name: finance_legacy_accepted_documents; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"finance_legacy_accepted_documents\\" (\n    \\"document_type\\" \\"text\\" NOT NULL,\n    \\"document_id\\" \\"uuid\\" NOT NULL,\n    \\"classification\\" \\"text\\" NOT NULL,\n    \\"acceptance_reason\\" \\"text\\" NOT NULL,\n    \\"accepted_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"finance_legacy_accepted_documents_classification_check\\" CHECK ((\\"classification\\" = 'legacy_accepted'::\\"text\\")),\n    CONSTRAINT \\"finance_legacy_accepted_documents_document_type_check\\" CHECK ((\\"document_type\\" = 'fund_transfer'::\\"text\\"))\n)","--\n-- Name: unbalanced_journal_entries; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"unbalanced_journal_entries\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"id\\",\n    \\"entry_number\\",\n    \\"entry_date\\",\n    \\"total_debit\\",\n    \\"total_credit\\",\n    (\\"total_debit\\" - \\"total_credit\\") AS \\"difference\\",\n    \\"description\\",\n    \\"created_at\\"\n   FROM \\"public\\".\\"journal_entries\\"\n  WHERE ((\\"abs\\"((\\"total_debit\\" - \\"total_credit\\")) >= 0.01) AND (NOT ((\\"total_debit\\" = (0)::numeric) AND (\\"total_credit\\" = (0)::numeric))))\n  ORDER BY \\"created_at\\" DESC","--\n-- Name: finance_live_verification_failures; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"finance_live_verification_failures\\" WITH (\\"security_invoker\\"='true') AS\n WITH \\"bank_failures\\" AS (\n         SELECT \\"b\\".\\"id\\",\n            \\"b\\".\\"upload_id\\",\n            \\"b\\".\\"bank_account_id\\",\n            \\"b\\".\\"transaction_date\\",\n            \\"b\\".\\"description\\",\n            \\"b\\".\\"reference\\",\n            \\"b\\".\\"branch_code\\",\n            \\"b\\".\\"debit_amount\\",\n            \\"b\\".\\"credit_amount\\",\n            \\"b\\".\\"running_balance\\",\n            \\"b\\".\\"currency\\",\n            \\"b\\".\\"reconciliation_status\\",\n            \\"b\\".\\"matched_entry_id\\",\n            \\"b\\".\\"matched_expense_id\\",\n            \\"b\\".\\"matched_receipt_id\\",\n            \\"b\\".\\"matched_at\\",\n            \\"b\\".\\"matched_by\\",\n            \\"b\\".\\"notes\\",\n            \\"b\\".\\"created_by\\",\n            \\"b\\".\\"created_at\\",\n            \\"b\\".\\"statement_balance\\",\n            \\"b\\".\\"transaction_hash\\",\n            \\"b\\".\\"matched_petty_cash_id\\",\n            \\"b\\".\\"matched_fund_transfer_id\\",\n            \\"b\\".\\"paid_by\\",\n            \\"b\\".\\"matching_status\\",\n            \\"b\\".\\"manually_unlinked\\",\n            \\"b\\".\\"payment_kind\\",\n            \\"b\\".\\"matched_tax_payment_id\\",\n            \\"b\\".\\"matched_payment_id\\",\n            \\"ba\\".\\"coa_id\\" AS \\"bank_coa_id\\",\n            \\"ba\\".\\"bank_name\\",\n            \\"ba\\".\\"account_name\\",\n            \\"ba\\".\\"account_number\\",\n            \\"ba\\".\\"currency\\" AS \\"bank_currency\\",\n            \\"je\\".\\"id\\" AS \\"active_journal_id\\",\n            \\"je\\".\\"entry_number\\",\n                CASE\n                    WHEN (\\"ba\\".\\"coa_id\\" IS NULL) THEN 'The selected bank is missing its posting account.'::\\"text\\"\n                    WHEN (\\"je\\".\\"id\\" IS NULL) THEN 'The linked bank transaction has no active journal.'::\\"text\\"\n                    WHEN (NOT (EXISTS ( SELECT 1\n                       FROM \\"public\\".\\"journal_entry_lines\\" \\"x\\"\n                      WHERE ((\\"x\\".\\"journal_entry_id\\" = \\"je\\".\\"id\\") AND (\\"x\\".\\"account_id\\" = \\"ba\\".\\"coa_id\\"))))) THEN 'The linked journal uses a different account from the Bank Master.'::\\"text\\"\n                    ELSE 'The amount or money-in/money-out direction differs between the bank transaction and journal.'::\\"text\\"\n                END AS \\"problem\\"\n           FROM ((\\"public\\".\\"bank_statement_lines\\" \\"b\\"\n             LEFT JOIN \\"public\\".\\"bank_accounts\\" \\"ba\\" ON ((\\"ba\\".\\"id\\" = \\"b\\".\\"bank_account_id\\")))\n             LEFT JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON (((\\"je\\".\\"id\\" = \\"b\\".\\"matched_entry_id\\") AND (\\"je\\".\\"is_posted\\" = true) AND (COALESCE(\\"je\\".\\"is_reversed\\", false) = false))))\n          WHERE (((\\"b\\".\\"reconciliation_status\\" = ANY (ARRAY['matched'::\\"text\\", 'recorded'::\\"text\\"])) OR (\\"b\\".\\"matched_entry_id\\" IS NOT NULL)) AND ((\\"ba\\".\\"coa_id\\" IS NULL) OR (\\"je\\".\\"id\\" IS NULL) OR (NOT (EXISTS ( SELECT 1\n                   FROM \\"public\\".\\"journal_entry_lines\\" \\"x\\"\n                  WHERE ((\\"x\\".\\"journal_entry_id\\" = \\"je\\".\\"id\\") AND (\\"x\\".\\"account_id\\" = \\"ba\\".\\"coa_id\\") AND (((COALESCE(\\"b\\".\\"credit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(\\"b\\".\\"debit_amount\\", (0)::numeric) = (0)::numeric) AND (COALESCE(NULLIF(\\"x\\".\\"transaction_debit\\", (0)::numeric), \\"x\\".\\"debit\\") = \\"b\\".\\"credit_amount\\")) OR ((COALESCE(\\"b\\".\\"debit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(\\"b\\".\\"credit_amount\\", (0)::numeric) = (0)::numeric) AND (COALESCE(NULLIF(\\"x\\".\\"transaction_credit\\", (0)::numeric), \\"x\\".\\"credit\\") = \\"b\\".\\"debit_amount\\")))))))))\n        ), \\"bank_rows\\" AS (\n         SELECT ('live:bank_reconciliation:'::\\"text\\" || (\\"b\\".\\"id\\")::\\"text\\") AS \\"row_id\\",\n            NULL::bigint AS \\"exception_id\\",\n            ( SELECT \\"finance_historical_repair_summary\\".\\"run_id\\"\n                   FROM \\"public\\".\\"finance_historical_repair_summary\\"\n                  ORDER BY \\"finance_historical_repair_summary\\".\\"started_at\\" DESC\n                 LIMIT 1) AS \\"run_id\\",\n            'bank_reconciliation'::\\"text\\" AS \\"document_type\\",\n            \\"b\\".\\"id\\" AS \\"document_id\\",\n            \\"b\\".\\"transaction_date\\" AS \\"date\\",\n            COALESCE(NULLIF(\\"b\\".\\"reference\\", ''::\\"text\\"), 'Bank transaction'::\\"text\\") AS \\"voucher_number\\",\n            (\\"b\\".\\"entry_number\\")::\\"text\\" AS \\"journal_number\\",\n            (COALESCE(NULLIF(\\"b\\".\\"debit_amount\\", (0)::numeric), \\"b\\".\\"credit_amount\\"))::numeric AS \\"amount\\",\n            COALESCE(\\"b\\".\\"currency\\", \\"b\\".\\"bank_currency\\", 'Unknown'::\\"text\\") AS \\"currency\\",\n            \\"concat_ws\\"(' · '::\\"text\\", \\"b\\".\\"bank_name\\", \\"b\\".\\"account_name\\", \\"b\\".\\"account_number\\", \\"b\\".\\"bank_currency\\") AS \\"bank\\",\n            COALESCE(\\"c\\".\\"company_name\\", (\\"s\\".\\"company_name\\")::\\"text\\") AS \\"customer_supplier\\",\n            \\"b\\".\\"payment_kind\\" AS \\"current_category\\",\n            \\"concat_ws\\"(' · '::\\"text\\", \\"coa\\".\\"code\\", \\"coa\\".\\"name\\") AS \\"current_gl_account\\",\n            'Verification failed'::\\"text\\" AS \\"status\\",\n            \\"b\\".\\"problem\\",\n            'The current bank link does not satisfy the Bank Master, amount and direction checks.'::\\"text\\" AS \\"why_not_automatic\\",\n            'Review the original bank transaction and source document, then select the confirmed bank and account. If the amounts differ, ask the accountant whether a formal correction is required.'::\\"text\\" AS \\"recommended_action\\",\n            \\"b\\".\\"bank_account_id\\" AS \\"current_bank_account_id\\",\n            \\"b\\".\\"active_journal_id\\" AS \\"journal_entry_id\\",\n            \\"current_line\\".\\"id\\" AS \\"journal_line_id\\",\n            \\"current_line\\".\\"account_id\\" AS \\"current_account_id\\",\n            NULL::\\"uuid\\" AS \\"current_tax_code_id\\",\n            \\"b\\".\\"payment_kind\\" AS \\"current_payment_type\\",\n            (\\"je\\".\\"source_module\\")::\\"text\\" AS \\"current_document_classification\\",\n            NULL::\\"text\\" AS \\"current_faktur_pajak_number\\",\n            NULL::numeric AS \\"expense_exchange_rate\\"\n           FROM ((((((((\\"bank_failures\\" \\"b\\"\n             LEFT JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"b\\".\\"active_journal_id\\")))\n             LEFT JOIN \\"public\\".\\"receipt_vouchers\\" \\"rv\\" ON ((\\"rv\\".\\"id\\" = \\"b\\".\\"matched_receipt_id\\")))\n             LEFT JOIN \\"public\\".\\"payment_vouchers\\" \\"pv\\" ON ((\\"pv\\".\\"id\\" = \\"b\\".\\"matched_payment_id\\")))\n             LEFT JOIN \\"public\\".\\"finance_expenses\\" \\"fe\\" ON ((\\"fe\\".\\"id\\" = \\"b\\".\\"matched_expense_id\\")))\n             LEFT JOIN \\"public\\".\\"customers\\" \\"c\\" ON ((\\"c\\".\\"id\\" = \\"rv\\".\\"customer_id\\")))\n             LEFT JOIN \\"public\\".\\"suppliers\\" \\"s\\" ON ((\\"s\\".\\"id\\" = COALESCE(\\"pv\\".\\"supplier_id\\", \\"fe\\".\\"supplier_id\\"))))\n             LEFT JOIN LATERAL ( SELECT \\"x\\".\\"id\\",\n                    \\"x\\".\\"account_id\\"\n                   FROM \\"public\\".\\"journal_entry_lines\\" \\"x\\"\n                  WHERE (\\"x\\".\\"journal_entry_id\\" = \\"b\\".\\"active_journal_id\\")\n                  ORDER BY\n                        CASE\n                            WHEN (((COALESCE(\\"b\\".\\"credit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF(\\"x\\".\\"transaction_debit\\", (0)::numeric), \\"x\\".\\"debit\\") = \\"b\\".\\"credit_amount\\")) OR ((COALESCE(\\"b\\".\\"debit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF(\\"x\\".\\"transaction_credit\\", (0)::numeric), \\"x\\".\\"credit\\") = \\"b\\".\\"debit_amount\\"))) THEN 0\n                            ELSE 1\n                        END, \\"x\\".\\"line_number\\"\n                 LIMIT 1) \\"current_line\\" ON (true))\n             LEFT JOIN \\"public\\".\\"chart_of_accounts\\" \\"coa\\" ON ((\\"coa\\".\\"id\\" = \\"current_line\\".\\"account_id\\")))\n        ), \\"journal_rows\\" AS (\n         SELECT ('live:journal:'::\\"text\\" || (\\"u\\".\\"id\\")::\\"text\\") AS \\"?column?\\",\n            NULL::bigint AS \\"int8\\",\n            ( SELECT \\"finance_historical_repair_summary\\".\\"run_id\\"\n                   FROM \\"public\\".\\"finance_historical_repair_summary\\"\n                  ORDER BY \\"finance_historical_repair_summary\\".\\"started_at\\" DESC\n                 LIMIT 1) AS \\"run_id\\",\n            'journal'::\\"text\\" AS \\"text\\",\n            \\"u\\".\\"id\\",\n            \\"u\\".\\"entry_date\\",\n            (\\"u\\".\\"entry_number\\")::\\"text\\" AS \\"entry_number\\",\n            (\\"u\\".\\"entry_number\\")::\\"text\\" AS \\"entry_number\\",\n            (\\"u\\".\\"total_debit\\")::numeric AS \\"total_debit\\",\n            'IDR'::\\"text\\" AS \\"text\\",\n            NULL::\\"text\\" AS \\"text\\",\n            NULL::\\"text\\" AS \\"text\\",\n            \\"u\\".\\"description\\",\n            NULL::\\"text\\" AS \\"text\\",\n            'Verification failed'::\\"text\\" AS \\"text\\",\n            'This posted journal is not balanced.'::\\"text\\" AS \\"text\\",\n            'Finance reports require every posted journal to have equal debits and credits.'::\\"text\\" AS \\"text\\",\n            'Review the source document and journal with the accountant. Do not change historical amounts without an authorised correction.'::\\"text\\" AS \\"text\\",\n            NULL::\\"uuid\\" AS \\"uuid\\",\n            \\"u\\".\\"id\\",\n            NULL::\\"uuid\\" AS \\"uuid\\",\n            NULL::\\"uuid\\" AS \\"uuid\\",\n            NULL::\\"uuid\\" AS \\"uuid\\",\n            NULL::\\"text\\" AS \\"text\\",\n            NULL::\\"text\\" AS \\"text\\",\n            NULL::\\"text\\" AS \\"text\\",\n            NULL::numeric AS \\"numeric\\"\n           FROM \\"public\\".\\"unbalanced_journal_entries\\" \\"u\\"\n        ), \\"faktur_rows\\" AS (\n         SELECT ('live:sales_invoice:'::\\"text\\" || (\\"si\\".\\"id\\")::\\"text\\") AS \\"?column?\\",\n            NULL::bigint AS \\"int8\\",\n            ( SELECT \\"finance_historical_repair_summary\\".\\"run_id\\"\n                   FROM \\"public\\".\\"finance_historical_repair_summary\\"\n                  ORDER BY \\"finance_historical_repair_summary\\".\\"started_at\\" DESC\n                 LIMIT 1) AS \\"run_id\\",\n            'sales_invoice'::\\"text\\" AS \\"text\\",\n            \\"si\\".\\"id\\",\n            \\"si\\".\\"invoice_date\\",\n            \\"si\\".\\"invoice_number\\",\n            (\\"je\\".\\"entry_number\\")::\\"text\\" AS \\"entry_number\\",\n            (\\"si\\".\\"total_amount\\")::numeric AS \\"total_amount\\",\n            'IDR'::\\"text\\" AS \\"text\\",\n     