\\" USING \\"btree\\" (\\"source_module\\", \\"reference_id\\") WHERE (((\\"source_module\\")::\\"text\\" = 'petty_cash'::\\"text\\") AND (\\"reference_id\\" IS NOT NULL))","--\n-- Name: uniq_journal_entries_source_ref_number; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uniq_journal_entries_source_ref_number\\" ON \\"public\\".\\"journal_entries\\" USING \\"btree\\" (\\"source_module\\", \\"reference_number\\") WHERE ((\\"reference_number\\" IS NOT NULL) AND (\\"source_module\\" IS NOT NULL) AND (NOT COALESCE(\\"is_reversed\\", false)))","--\n-- Name: uniq_petty_cash_resolved_tx_id; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uniq_petty_cash_resolved_tx_id\\" ON \\"public\\".\\"journal_entries\\" USING \\"btree\\" (\\"source_module\\", \\"public\\".\\"petty_cash_resolved_tx_id\\"(\\"reference_id\\", (\\"reference_number\\")::\\"text\\")) WHERE (((\\"source_module\\")::\\"text\\" = 'petty_cash'::\\"text\\") AND (\\"public\\".\\"petty_cash_resolved_tx_id\\"(\\"reference_id\\", (\\"reference_number\\")::\\"text\\") IS NOT NULL))","--\n-- Name: uq_active_bank_document_journal; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_active_bank_document_journal\\" ON \\"public\\".\\"journal_entries\\" USING \\"btree\\" (\\"source_module\\", \\"reference_id\\") WHERE ((\\"reference_id\\" IS NOT NULL) AND (\\"is_posted\\" = true) AND (COALESCE(\\"is_reversed\\", false) = false) AND ((\\"reference_number\\")::\\"text\\" IS DISTINCT FROM (\\"entry_number\\")::\\"text\\") AND ((\\"source_module\\")::\\"text\\" = ANY ((ARRAY['expenses'::character varying, 'payment'::character varying, 'receipt'::character varying, 'petty_cash'::character varying, 'fund_transfers'::character varying, 'tax_payment'::character varying])::\\"text\\"[])))","--\n-- Name: uq_active_customer_normalized_name; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_active_customer_normalized_name\\" ON \\"public\\".\\"customer